const wait = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const page = (await (await fetch('http://127.0.0.1:9222/json/list')).json()).find(t => t.type === 'page' && t.url.startsWith('http://127.0.0.1:8765/'));
  const ws = new WebSocket(page.webSocketDebuggerUrl); let seq = 0; const pending = new Map();
  ws.onmessage = e => { const m=JSON.parse(e.data); if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);} };
  await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject;});
  const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;pending.set(id,m=>m.error?reject(new Error(m.error.message)):resolve(m));ws.send(JSON.stringify({id,method,params}));});
  const ev=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true})).result.result.value;
  await call('Runtime.enable');await call('Page.enable');
  await ev(`document.querySelector('#restartBtn').click()`); await wait(1300);
  const c=await ev(`(()=>{const r=document.querySelector('#game').getBoundingClientRect();return {left:r.left,top:r.top,width:r.width,height:r.height}})()`);
  // Use same tested canvas tile mapping: adjacent east of the player's start.
  const tile=Math.max(24,Math.min(40,c.width/25,c.height/16)); const point={x:c.left+c.width/2+tile,y:c.top+c.height/2};
  await ev(`(()=>{const s=document.querySelector('#npcPicker');s.value='chaoticPaladin';s.dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('#npcPlaceToggle').click()})()`);
  await call('Input.dispatchMouseEvent',{type:'mouseMoved',...point});await call('Input.dispatchMouseEvent',{type:'mousePressed',...point,button:'left',clickCount:1});await call('Input.dispatchMouseEvent',{type:'mouseReleased',...point,button:'left',clickCount:1});
  const placed=await ev(`({toast:document.querySelector('#toast').textContent,target:document.querySelector('#targetName').textContent,status:document.querySelector('#targetStatus').textContent})`);
  await ev(`document.dispatchEvent(new KeyboardEvent('keydown',{key:'f',bubbles:true}))`);
  const result=await ev(`({toast:document.querySelector('#toast').textContent,target:document.querySelector('#targetName').textContent,status:document.querySelector('#targetStatus').textContent,log:document.querySelector('#battleLog').innerText,feed:document.querySelector('#killFeed').innerText})`);
  console.log(JSON.stringify({point,placed,result},null,2)); ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

