const wait = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const page = (await (await fetch('http://127.0.0.1:9222/json/list')).json()).find(t => t.type === 'page' && t.url.startsWith('http://127.0.0.1:8765/'));
  const ws = new WebSocket(page.webSocketDebuggerUrl); let seq = 0; const pending = new Map();
  ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  const call = (method, params = {}) => new Promise((resolve, reject) => { const id = ++seq; pending.set(id, m => m.error ? reject(new Error(m.error.message)) : resolve(m)); ws.send(JSON.stringify({id, method, params})); });
  const ev = async expression => (await call('Runtime.evaluate', {expression, returnByValue: true})).result.result.value;
  await call('Page.enable'); await call('Runtime.enable');
  await call('Page.reload', {ignoreCache: true}); await wait(2500);
  await ev(`document.querySelector('#restartBtn').click()`); await wait(200);
  const p = await ev(`(()=>{const r=document.querySelector('#game').getBoundingClientRect();return {x:r.left+r.width/2+24,y:r.top+r.height/2,width:r.width,height:r.height}})()`);
  await ev(`(()=>{let s=document.querySelector('#npcPicker');s.value='chaoticPaladin';s.dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('#npcPlaceToggle').click()})()`);
  await call('Input.dispatchMouseEvent',{type:'mouseMoved',x:p.x,y:p.y});
  await call('Input.dispatchMouseEvent',{type:'mousePressed',x:p.x,y:p.y,button:'left',clickCount:1});
  await call('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x,y:p.y,button:'left',clickCount:1});
  const states=[];
  for(let i=0;i<80;i++) {
    const s=await ev(`({buttonDisabled:document.querySelector('#attackBtn').disabled,target:document.querySelector('#targetName').textContent,targetStatus:document.querySelector('#targetStatus').textContent,hp:document.querySelector('#healthValue').textContent,potionDisabled:document.querySelector('#healthPotion').disabled,toast:document.querySelector('#toast').textContent,log:document.querySelector('#battleLog').innerText,score:document.querySelector('#progressText').textContent})`);
    if(!s.buttonDisabled) { states.push({i,before:s}); await ev(`document.querySelector('#attackBtn').click()`); await wait(30); states.push({after:await ev(`({buttonDisabled:document.querySelector('#attackBtn').disabled,targetStatus:document.querySelector('#targetStatus').textContent,hp:document.querySelector('#healthValue').textContent,toast:document.querySelector('#toast').textContent,log:document.querySelector('#battleLog').innerText,feed:document.querySelector('#killFeed').innerText})`)}); break; }
    if(i%10===0) states.push({i,s}); await wait(50);
  }
  console.log(JSON.stringify({p,states,end:await ev(`({time:document.querySelector('#timer').textContent,hp:document.querySelector('#healthValue').textContent,roster:[...document.querySelectorAll('[data-fighter]')].map(e=>[e.dataset.fighter,e.className])})`)},null,2)); ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

